create table if not exists maintenance_parts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),part_number text not null,description text not null,manufacturer text,unit_cost numeric(12,2) not null default 0,reorder_point numeric(14,2) not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,part_number));
create table if not exists maintenance_inventory_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,code text,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists maintenance_inventory_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),part_id uuid not null references maintenance_parts(id),location_id uuid not null references maintenance_inventory_locations(id),work_order_id uuid references maintenance_work_orders(id),transaction_type text not null check(transaction_type in('receipt','issue','return','adjustment')),quantity numeric(14,2) not null check(quantity<>0),unit_cost_snapshot numeric(12,2) not null default 0,notes text,created_by uuid,created_by_email text,created_at timestamptz not null default now(),check((transaction_type in('receipt','return')and quantity>0)or(transaction_type='issue'and quantity<0)or transaction_type='adjustment'));
create index if not exists maintenance_inventory_part_location_idx on maintenance_inventory_transactions(part_id,location_id,created_at);create index if not exists maintenance_inventory_wo_idx on maintenance_inventory_transactions(work_order_id)where work_order_id is not null;
alter table maintenance_parts enable row level security;alter table maintenance_inventory_locations enable row level security;alter table maintenance_inventory_transactions enable row level security;revoke all on maintenance_parts,maintenance_inventory_locations,maintenance_inventory_transactions from anon,authenticated;grant all on maintenance_parts,maintenance_inventory_locations,maintenance_inventory_transactions to service_role;
create or replace view maintenance_part_stock_levels as select p.organization_id,p.id part_id,p.part_number,p.description,p.manufacturer,p.unit_cost,p.reorder_point,l.id location_id,l.name location,coalesce(sum(t.quantity),0)::numeric(14,2) stock_on_hand from maintenance_parts p cross join maintenance_inventory_locations l left join maintenance_inventory_transactions t on t.part_id=p.id and t.location_id=l.id where p.active and l.active and p.organization_id=l.organization_id group by p.organization_id,p.id,l.id;
create or replace function maintenance_post_inventory(p_organization_id uuid,p_part_id uuid,p_location_id uuid,p_work_order_id uuid,p_type text,p_quantity numeric,p_unit_cost numeric,p_notes text,p_actor_id uuid,p_actor_email text)returns uuid language plpgsql security definer set search_path=public as $$declare id uuid;q numeric;available numeric;begin if p_quantity<=0 then raise exception'Quantity must be positive';end if;if not exists(select 1 from maintenance_parts where id=p_part_id and organization_id=p_organization_id and active)or not exists(select 1 from maintenance_inventory_locations where id=p_location_id and organization_id=p_organization_id and active)then raise exception'Invalid inventory reference';end if;q:=case when p_type='issue'then-p_quantity else p_quantity end;if p_type='issue'then select coalesce(sum(quantity),0)into available from maintenance_inventory_transactions where part_id=p_part_id and location_id=p_location_id;if available<p_quantity then raise exception'Insufficient stock';end if;end if;insert into maintenance_inventory_transactions(organization_id,part_id,location_id,work_order_id,transaction_type,quantity,unit_cost_snapshot,notes,created_by,created_by_email)values(p_organization_id,p_part_id,p_location_id,p_work_order_id,p_type,q,p_unit_cost,p_notes,p_actor_id,p_actor_email)returning maintenance_inventory_transactions.id into id;return id;end$$;
revoke all on function maintenance_post_inventory(uuid,uuid,uuid,uuid,text,numeric,numeric,text,uuid,text)from public,anon,authenticated;grant execute on function maintenance_post_inventory(uuid,uuid,uuid,uuid,text,numeric,numeric,text,uuid,text)to service_role;